// Minimal Darwin NCE runtime used by the validation tests.
//
// It keeps the data structures and the entry/exit protocol of the existing NCE
// (GuestContext, NativeExecutionParameters, the lock word, the post-SVC trampolines
// generated by the real nce/patcher.cpp) and changes only what the Darwin tests show
// must change:
//   - the thread parameters pointer is read from a TSD slot of TPIDRRO_EL0,
//   - guest/host is decided from the PC (guest code only runs inside the guest window),
//   - Darwin signal frames (__darwin_mcontext64) instead of Linux ones.
#pragma once

#include <atomic>
#include <cstdint>
#include <mach/mach.h>
#include <pthread.h>
#include <signal.h>
#include <string>
#include <unordered_map>
#include <vector>

#include "darwin_ctx.h"
#include "nce/guest_context.h"

namespace ncev {

extern std::uint32_t g_params_slot_offset;

// Halt reason bits, as the existing NCE returns them (Dynarmic encoding).
std::uint64_t HrSupervisorCall();
std::uint64_t HrBreakLoop();
std::uint64_t HrBreakpoint();
std::uint64_t HrDataAbort();
std::uint64_t HrPrefetchAbort();

struct Vcpu;
using FaultHook = bool (*)(Vcpu & vcpu, int sig, siginfo_t * info, Mcontext * mc);

struct Vcpu {
    // Must stay the first member: the signal handlers find the Vcpu from
    // NativeExecutionParameters::native_context.
    Core::GuestContext ctx{};
    NativeExecutionParameters params{};
    const std::unordered_map<std::uint64_t, std::uint64_t> * post_handlers = nullptr;
    mach_port_t port = MACH_PORT_NULL;
    pthread_t thread{};

    std::uint64_t host_fpcr = 0;
    std::uint64_t host_fpsr = 0;
    bool restore_host_fp_on_signal_exit = true;

    int exit_signal = 0;
    std::uint64_t exit_far = 0;
    std::uint32_t exit_esr = 0;
    std::uint64_t entries_signal = 0;
    std::uint64_t entries_trampoline = 0;

    FaultHook fault_hook = nullptr;
    void * user = nullptr;

    Vcpu();
    // Binds the vcpu to the calling host thread (TSD slot, signal stack).
    void BindThread();
    // PhysicalCore::RunThread + ArmNce::RunThread: lock, enter, exit, unlock.
    std::uint64_t Run();
    // ArmNce::SignalInterrupt, called from another host thread.
    void SignalInterrupt();
};

// Installs the TSD key and the signal handlers. The guest windows are the ranges where
// guest code (modules and patch sections) is mapped; the last one serves WindowAlloc.
void RuntimeInit(const std::vector<std::pair<std::uint64_t, std::uint64_t>> & windows);
bool InGuestWindow(std::uint64_t pc);
void LockParams(NativeExecutionParameters * params);
void UnlockParams(NativeExecutionParameters * params);
void BindSignalStack();

// Statistics of signals that hit host code (ignored interrupts, chained faults).
extern std::atomic<std::uint64_t> g_spurious_interrupts;

// Guest memory helpers inside the reserved window.
std::uint64_t WindowAlloc(std::uint64_t size, int prot);
void WindowProtect(std::uint64_t addr, std::uint64_t size, int prot);

struct GuestImage {
    std::uint64_t base = 0;
    std::uint64_t size = 0;
    std::uint64_t code_offset = 0; // offset of code_words[0] in the image
    std::unordered_map<std::uint64_t, std::uint64_t> post_handlers;
    std::uint64_t patch_section_size = 0;
    std::unordered_map<std::uint64_t, std::uint64_t> read_handlers, restart_pcs;
};

// Places `code_words` in a module text, runs the real Patcher on it and maps the
// result read+execute in the guest window. `patched_words` (optional) receives the
// module text after relocation.
bool BuildPatchedImage(const std::vector<std::uint32_t> & code_words, GuestImage & out, std::string & error,
                       std::vector<std::uint32_t> * patched_words = nullptr, bool run_patcher = true, bool legacy_36bit = false, bool legacy_36bit_sdk = false, std::uint64_t read_table = 0, bool all_read_bases = false, bool float_reads = false, bool store_thunks = false);

// Writes words to an already mapped RX image (W^X toggle + icache invalidation).
void PatchImageWord(const GuestImage & image, std::uint64_t addr, std::uint32_t word);

// Random guest state.
struct HostFpMasks {
    std::uint32_t fpcr_writable;
    std::uint32_t fpsr_writable;
};
HostFpMasks ProbeFpMasks();

} // namespace ncev

extern "C" std::uint64_t ncev_enter_trampoline(void * params, Core::GuestContext * ctx, std::uint64_t trampoline);
extern "C" std::uint64_t ncev_enter_signal(mach_port_t thread, void * params, Core::GuestContext * ctx);
extern "C" std::uint64_t ncev_call_check_callee_saved(std::uint64_t (*fn)(void *), void * arg);
